// Generated by `bun run learning`. Typed loosely here so TypeScript doesn't
// infer a type from 1.5 MB of JSON; src/lib/learning.ts owns the real shapes.
declare module "@/server/learning-index.json" {
  const value: unknown;
  export default value;
}
declare module "@/server/learning-notes.json" {
  const value: Record<string, unknown>;
  export default value;
}
